    call momtran(lchnk, ncol, domomtran, q, ncnst, mu, md, du, eu, ed, dp, dsubcld, jt, mx, ideep, il1g, il2g, nstep, dqdt, pguall, pgdall, icwu, icwd, dt, seten)
