    z_dt = 0.0_c_double
    zp_dt => z_dt
    call torch_tensor_from_array(in_t(14), zp_dt, torch_kCPU)
    yp_dqdt => y_dqdt
    call torch_tensor_from_array(out_t(1), yp_dqdt, torch_kCPU)
    yp_pguall => y_pguall
    call torch_tensor_from_array(out_t(2), yp_pguall, torch_kCPU)
