    call torch_delete(out_t)
  end subroutine warm_compute_eddy_diff

  subroutine warm_model(hook)
    integer(c_int), intent(in) :: hook
    select case (hook)
    case (1)
      call warm_cldfrc_fice()
    case (3)
      call warm_instratus_condensate()
    case (4)
      call warm_micro_mg_tend()
    case (5)
      call warm_compute_tms()
    case (6)
      call warm_compute_uwshcu_inv()
    case (7)
      call warm_mmacro_pcond()
    case (8)
      call warm_zm_conv_evap()
    case (9)
      call warm_momtran()
    case (10)
      call warm_zm_convr()
    case (11)
      call warm_compute_eddy_diff()
    end select
  end subroutine warm_model

  ! ------------------------------------------------------------------ !
  ! The ABI the runners and Python drive
  ! ------------------------------------------------------------------ !

  integer(c_int) function pycam_hooks_count_v1() bind(C, name='pycam_hooks_count_v1') result(count)
    count = int(nhooks, c_int)
  end function pycam_hooks_count_v1

  integer(c_int) function pycam_hooks_name_v1(hook, buffer, length) bind(C, name='pycam_hooks_name_v1') result(status)
    integer(c_int), value, intent(in) :: hook, length
    character(kind=c_char), intent(out) :: buffer(*)
    character(len=64) :: name
    integer :: i
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    select case (hook)
    case (1)
      name = name_1
    case (2)
      name = name_2
    case (3)
      name = name_3
    case (4)
      name = name_4
    case (5)
      name = name_5
    case (6)
      name = name_6
    case (7)
      name = name_7
    case (8)
      name = name_8
    case (9)
      name = name_9
    case (10)
      name = name_10
    case (11)
      name = name_11
    end select
    do i = 1, min(int(length) - 1, len_trim(name))
      buffer(i) = name(i:i)
    end do
    buffer(min(int(length), len_trim(name) + 1)) = c_null_char
    status = 0_c_int
  end function pycam_hooks_name_v1

  integer(c_int) function pycam_hooks_arm_v1(hook, flag) bind(C, name='pycam_hooks_arm_v1') result(status)
    ! arm (flag /= 0) or disarm one hook: the owning stage does this around its run
    integer(c_int), value, intent(in) :: hook, flag
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    if (flag /= 0_c_int .and. modeled(hook)) then
      status = 3_c_int; return          ! a bound model and a Python replacement cannot share a hook
    end if
    if (flag /= 0_c_int .and. .not. can_pause(hook)) then
      status = 5_c_int; return          ! a Fortran-bound hook has no frame to hand Python
    end if
    armed(hook) = flag /= 0_c_int
    status = 0_c_int
  end function pycam_hooks_arm_v1

  integer(c_int) function pycam_hooks_bind_model_v1(hook, path, length, shadow_flag) &
       bind(C, name='pycam_hooks_bind_model_v1') result(status)
    ! load the TorchScript file at path (length bytes) and answer the hook's calls with it from
    ! now on; with shadow_flag /= 0 the model runs but the original keeps answering
    integer(c_int), value, intent(in) :: hook, length, shadow_flag
    character(kind=c_char), intent(in) :: path(*)
    character(len=4096) :: filename
    integer :: i
    integer(c_int64_t) :: w0, w1
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    if (.not. has_model(hook)) then
      status = 2_c_int; return
    end if
    if (armed(hook)) then
      status = 3_c_int; return
    end if
    if (length < 1 .or. length > len(filename)) then
      status = 4_c_int; return
    end if
    filename = ' '
    do i = 1, length
      filename(i:i) = path(i)
    end do
    if (modeled(hook) .and. .not. plugged(hook)) call torch_delete(models(hook))
    plugged(hook) = .false.; plugins(hook) = c_null_funptr
    call torch_model_load(models(hook), filename(1:length), torch_kCPU)
    ! one forward on zeros now: the first step does not pay the model's warm-up
    call system_clock(w0)
    call warm_model(hook)
    call system_clock(w1)
    warm_ticks(hook) = w1 - w0
    modeled(hook) = .true.
    shadow(hook) = shadow_flag /= 0_c_int
    status = 0_c_int
  end function pycam_hooks_bind_model_v1

  integer(c_int) function pycam_hooks_unbind_model_v1(hook) bind(C, name='pycam_hooks_unbind_model_v1') result(status)
    ! release the bound model or plugin: the hook answers with the original again
    integer(c_int), value, intent(in) :: hook
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    if (modeled(hook)) then
      if (.not. plugged(hook)) call torch_delete(models(hook))
      modeled(hook) = .false.
      plugged(hook) = .false.
      plugins(hook) = c_null_funptr
      shadow(hook) = .false.
    end if
    status = 0_c_int
  end function pycam_hooks_unbind_model_v1

  integer(c_int) function pycam_hooks_bind_plugin_v1(hook, plugin, shadow_flag) &
       bind(C, name='pycam_hooks_bind_plugin_v1') result(status)
    ! bind a compiled plugin (a C function of the plugin_interface, e.g. a Numba cfunc) at the
    ! hook: from now on the hook hands it the model block's arrays as pointer and extent tables
    ! and takes its outputs, with no Python in the step; shadow as for a model
    integer(c_int), value, intent(in) :: hook, shadow_flag
    type(c_funptr), value, intent(in) :: plugin
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    if (.not. has_model(hook)) then
      status = 2_c_int; return
    end if
    if (armed(hook)) then
      status = 3_c_int; return
    end if
    if (modeled(hook) .and. .not. plugged(hook)) call torch_delete(models(hook))
    plugins(hook) = plugin
    plugged(hook) = .true.
    modeled(hook) = .true.
    shadow(hook) = shadow_flag /= 0_c_int
    status = 0_c_int
  end function pycam_hooks_bind_plugin_v1

  integer(c_int) function pycam_hooks_model_seconds_v1(hook, model_seconds, forward_seconds, call_seconds, &
       first_seconds, warm_seconds, original_seconds) bind(C, name='pycam_hooks_model_seconds_v1') result(status)
    ! wall seconds this rank spent in the hook's model branch, in the model's forward alone,
    ! around the whole model call as the hook sees it (prologue and epilogue included), in the
    ! first modeled call alone, in the warm-up forward at bind, and in the original on the calls
    ! a shadow model also answered
    integer(c_int), value, intent(in) :: hook
    real(c_double), intent(out) :: model_seconds, forward_seconds, call_seconds, first_seconds, warm_seconds
    real(c_double), intent(out) :: original_seconds
    integer(c_int64_t) :: rate
    model_seconds = 0.0_c_double; forward_seconds = 0.0_c_double; call_seconds = 0.0_c_double
    first_seconds = 0.0_c_double; warm_seconds = 0.0_c_double; original_seconds = 0.0_c_double
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    call system_clock(count_rate=rate)
    model_seconds = real(model_ticks(hook), c_double) / real(rate, c_double)
    forward_seconds = real(forward_ticks(hook), c_double) / real(rate, c_double)
    call_seconds = real(hook_ticks(hook), c_double) / real(rate, c_double)
    first_seconds = real(first_ticks(hook), c_double) / real(rate, c_double)
    warm_seconds = real(warm_ticks(hook), c_double) / real(rate, c_double)
    original_seconds = real(original_ticks(hook), c_double) / real(rate, c_double)
    status = 0_c_int
  end function pycam_hooks_model_seconds_v1

  integer(c_int) function pycam_hooks_modeled_v1(hook, answered_out) bind(C, name='pycam_hooks_modeled_v1') result(status)
    ! calls the bound model answered inside the image
    integer(c_int), value, intent(in) :: hook
    integer(c_int64_t), intent(out) :: answered_out
    answered_out = 0_c_int64_t
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    answered_out = answered(hook)
    status = 0_c_int
  end function pycam_hooks_modeled_v1

  integer(c_int) function pycam_hooks_counts_v1(hook, calls_out, paused_out) bind(C, name='pycam_hooks_counts_v1') result(status)
    integer(c_int), value, intent(in) :: hook
    integer(c_int64_t), intent(out) :: calls_out, paused_out
    calls_out = 0_c_int64_t; paused_out = 0_c_int64_t
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    calls_out = calls(hook); paused_out = paused(hook)
    status = 0_c_int
  end function pycam_hooks_counts_v1

  integer(c_int) function pycam_hooks_missed_v1(hook, missed_out) bind(C, name='pycam_hooks_missed_v1') result(status)
    ! calls that found the hook armed while no fiber was running: the original answered them
    integer(c_int), value, intent(in) :: hook
    integer(c_int64_t), intent(out) :: missed_out
    missed_out = 0_c_int64_t
    status = 1_c_int
    if (hook < 1 .or. hook > nhooks) return
    missed_out = missed(hook)
    status = 0_c_int
  end function pycam_hooks_missed_v1

  integer(c_int) function pycam_hooks_paused_v1() bind(C, name='pycam_hooks_paused_v1') result(hook)
    ! the hook suspended on the fiber now, or 0
    hook = int(paused_hook, c_int)
  end function pycam_hooks_paused_v1

  integer(c_int) function pycam_hooks_frame_v1(count, ptrs, ndims, shapes, dtypes, intents, ncol_out) &
       bind(C, name='pycam_hooks_frame_v1') result(status)
    ! the paused call's arguments in the callee's order, where they live
    integer(c_int), value, intent(in) :: count
    type(c_ptr), intent(out) :: ptrs(count)
    integer(c_int), intent(out) :: ndims(count), dtypes(count), intents(count), ncol_out
    integer(c_int64_t), intent(out) :: shapes(max_rank, count)
    integer :: slot
    status = 1_c_int
    ncol_out = 0_c_int
    if (paused_hook == 0) return
    if (count < frame_nslots) then
      status = 3_c_int; return
    end if
    do slot = 1, count
      ptrs(slot) = c_null_ptr; ndims(slot) = 0_c_int; dtypes(slot) = 0_c_int; intents(slot) = 0_c_int
      shapes(:, slot) = 0_c_int64_t
    end do
    do slot = 1, frame_nslots
      ptrs(slot) = frame_ptrs(slot); ndims(slot) = frame_ndims(slot)
      dtypes(slot) = frame_dtypes(slot); intents(slot) = frame_intents(slot)
      shapes(:, slot) = frame_shapes(:, slot)
    end do
    ncol_out = frame_ncol
    status = 0_c_int
  end function pycam_hooks_frame_v1

  integer(c_int) function pycam_hooks_original_v1() bind(C, name='pycam_hooks_original_v1') result(status)
    ! run the original on the paused frame, from the main context
    integer(c_int), pointer :: s1_i
    real(c_double), pointer :: p2_f2(:,:)
    real(c_double), pointer :: p3_f2(:,:)
    real(c_double), pointer :: p4_f2(:,:)
    real(c_double), pointer :: s1_f
    real(c_double), pointer :: p2_f1(:)
    integer(c_int), pointer :: s3_i
    integer(c_int), pointer :: s4_i
    real(c_double), pointer :: s5_f
    real(c_double), pointer :: s6_f
    real(c_double), pointer :: s7_f
    real(c_double), pointer :: s8_f
    real(c_double), pointer :: s9_f
    real(c_double), pointer :: p10_f1(:)
    integer(c_int), pointer :: s2_i
    real(c_double), pointer :: p4_f1(:)
    real(c_double), pointer :: p5_f1(:)
    real(c_double), pointer :: p6_f1(:)
    real(c_double), pointer :: p7_f1(:)
    real(c_double), pointer :: p8_f1(:)
    real(c_double), pointer :: p9_f1(:)
    real(c_double), pointer :: p11_f1(:)
    real(c_double), pointer :: p12_f1(:)
    real(c_double), pointer :: p13_f1(:)
    real(c_double), pointer :: p14_f1(:)
    real(c_double), pointer :: p15_f1(:)
    real(c_double), pointer :: p16_f1(:)
    real(c_double), pointer :: p17_f1(:)
    real(c_double), pointer :: p18_f1(:)
    real(c_double), pointer :: p19_f1(:)
    real(c_double), pointer :: p20_f1(:)
    real(c_double), pointer :: p21_f1(:)
    real(c_double), pointer :: p22_f1(:)
    real(c_double), pointer :: p23_f1(:)
    real(c_double), pointer :: p24_f1(:)
    real(c_double), pointer :: p25_f1(:)
    real(c_double), pointer :: p26_f1(:)
    real(c_double), pointer :: p27_f1(:)
    real(c_double), pointer :: p28_f1(:)
    real(c_double), pointer :: p29_f1(:)
    status = 1_c_int
    if (paused_hook == 0) return
    select case (paused_hook)
    case (1)
      call c_f_pointer(frame_ptrs(1), s1_i)
      call c_f_pointer(frame_ptrs(2), p2_f2, (/ 16, 30 /))
      call c_f_pointer(frame_ptrs(3), p3_f2, (/ 16, 30 /))
      call c_f_pointer(frame_ptrs(4), p4_f2, (/ 16, 30 /))
      call original_cldfrc_fice(s1_i, p2_f2, p3_f2, p4_f2)
    case (2)
      call c_f_pointer(frame_ptrs(1), s1_f)
      call c_f_pointer(frame_ptrs(2), p2_f1, (/ 31 /))
      call c_f_pointer(frame_ptrs(3), s3_i)
      call c_f_pointer(frame_ptrs(4), s4_i)
      call c_f_pointer(frame_ptrs(5), s5_f)
      call c_f_pointer(frame_ptrs(6), s6_f)
      call c_f_pointer(frame_ptrs(7), s7_f)
      call c_f_pointer(frame_ptrs(8), s8_f)
      call c_f_pointer(frame_ptrs(9), s9_f)
      call c_f_pointer(frame_ptrs(10), p10_f1, (/ 31 /))
      call original_fluxbelowinv(s1_f, p2_f1, s3_i, s4_i, s5_f, s6_f, s7_f, s8_f, s9_f, p10_f1)
    case (3)
      call c_f_pointer(frame_ptrs(1), s1_i)
      call c_f_pointer(frame_ptrs(2), s2_i)
      call c_f_pointer(frame_ptrs(3), s3_i)
      call c_f_pointer(frame_ptrs(4), p4_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(5), p5_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(6), p6_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(7), p7_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(8), p8_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(9), p9_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(10), p10_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(11), p11_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(12), p12_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(13), p13_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(14), p14_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(15), p15_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(16), p16_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(17), p17_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(18), p18_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(19), p19_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(20), p20_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(21), p21_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(22), p22_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(23), p23_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(24), p24_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(25), p25_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(26), p26_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(27), p27_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(28), p28_f1, (/ 16 /))
      call c_f_pointer(frame_ptrs(29), p29_f1, (/ 16 /))
      call original_instratus_condensate(s1_i, s2_i, s3_i, p4_f1, p5_f1, p6_f1, p7_f1, p8_f1, p9_f1, p10_f1, p11_f1, p12_f1, p13_f1, p14_f1, p15_f1, p16_f1, p17_f1, p18_f1, p19_f1, p20_f1, p21_f1, p22_f1, p23_f1, p24_f1, p25_f1, p26_f1, p27_f1, p28_f1, p29_f1)
    end select
    status = 0_c_int
  end function pycam_hooks_original_v1

  subroutine pycam_hooks_reset_v1() bind(C, name='pycam_hooks_reset_v1')
    integer :: hook
    armed = .false.
    paused_hook = 0
    do hook = 1, nhooks
      if (modeled(hook)) then
        call torch_delete(models(hook))
        modeled(hook) = .false.
        shadow(hook) = .false.
      end if
    end do
  end subroutine pycam_hooks_reset_v1

end module pycam_hooks
